// Chunk and clean text per politician
// Merge RSS headlines, Telegram messages, and X tweets
// Attach k-turns of thread context for sarcasm detection

const politicians = [
  { id: 'benjamin-netanyahu', name: 'Benjamin Netanyahu', party: 'Likud' },
  { id: 'yair-lapid', name: 'Yair Lapid', party: 'Yesh Atid' },
  { id: 'benny-gantz', name: 'Benny Gantz', party: 'National Unity' },
  { id: 'bezalel-smotrich', name: 'Bezalel Smotrich', party: 'Religious Zionism' },
  { id: 'avigdor-lieberman', name: 'Avigdor Lieberman', party: 'Yisrael Beiteinu' },
];

const results = [];
for (const pol of politicians) {
  // Filter and chunk text mentioning this politician
  // Attach thread context (preceding posts) for sarcasm detection
  // Attach speaker metadata (known_satirist flag)
  results.push({
    json: {
      politician: pol,
      headlines: [], // populated from RSS
      socialMentions: [], // populated from Telegram + X
    }
  });
}

return results;

// Parse LLM JSON response
// Strip markdown fences, validate field ranges

const raw = $json.content[0].text;
const cleaned = raw.replace(/^```json?\n?/m, '').replace(/\n?```$/m, '').trim();
const parsed = JSON.parse(cleaned);

// Validate ranges
if (parsed.hostility_level < 0 || parsed.hostility_level > 1) throw new Error('Invalid hostility_level');
if (parsed.policy_approval < -1 || parsed.policy_approval > 1) throw new Error('Invalid policy_approval');
if (parsed.media_amplification < 0 || parsed.media_amplification > 1) throw new Error('Invalid media_amplification');

return [{ json: parsed }];

// Compute deterministic overall_score from dimensional rubrics
// Formula: 0.4 * policy_normalized + 0.35 * (1 - hostility) + 0.25 * amplification

const WEIGHT_POLICY = 0.4;
const WEIGHT_HOSTILITY = 0.35;
const WEIGHT_AMPLIFICATION = 0.25;

const h = $json.hostility_level;
const p = $json.policy_approval;
const m = $json.media_amplification;

const policyNormalized = (p + 1) / 2;
const inverseHostility = 1 - h;
const overall = WEIGHT_POLICY * policyNormalized + WEIGHT_HOSTILITY * inverseHostility + WEIGHT_AMPLIFICATION * m;

$json.overall_score = parseFloat((overall * 10).toFixed(1));
$json.news_sentiment = parseFloat((policyNormalized * 10).toFixed(1));
$json.social_sentiment = parseFloat((inverseHostility * 10).toFixed(1));
$json.media_volume = parseFloat((m * 10).toFixed(1));

return [{ json: $json }];

// Run golden dataset validation (weekly check)
const dayOfWeek = new Date().getDay();
if (dayOfWeek !== 0) {
  // Skip validation on non-Sundays
  return [{ json: { validation_skipped: true, reason: 'Not Sunday' } }];
}

// On Sundays, run golden dataset MSE evaluation
// This would call the LLM against the golden dataset and compute MSE
// If MSE > 0.15, set drifted = true
return [{ json: { validation_run: true, mse: 0.0, drifted: false } }];

// Format summary + detail JSON artifacts for GitHub push

const today = new Date().toISOString().split('T')[0];
const entries = $input.all().map(item => item.json);

// Summary row (lightweight)
const summaryRows = entries.map(e => ({
  date: today,
  politician_id: e.politician_id,
  name: e.name,
  party: e.party,
  overall_score: e.overall_score,
  media_volume: e.media_volume,
}));

// Detail file (heavy, per-day)
const detailEntries = entries.map(e => ({
  politician_id: e.politician_id,
  name: e.name,
  party: e.party,
  hostility_level: e.hostility_level,
  policy_approval: e.policy_approval,
  media_amplification: e.media_amplification,
  news_sentiment: e.news_sentiment,
  social_sentiment: e.social_sentiment,
  media_volume: e.media_volume,
  overall_score: e.overall_score,
  chain_of_thought: e.chain_of_thought,
}));

return [
  { json: { type: 'summary', data: summaryRows, date: today } },
  { json: { type: 'detail', data: detailEntries, date: today } },
];
